/**
 * Version constants for the IaC generators (design-v2 4.4.12, review M3).
 *
 * One place drives: the `required_version` in every emitted `versions.tf`,
 * the provider pins, the static `.terraform.lock.hcl` files, the starter
 * pipelines (Phase 3) and our own `iac-validate` CI job (the job's matrix
 * must list TERRAFORM_VERSION and TERRAFORM_FLOOR_VERSION; a test checks it).
 *
 * Changing any value here changes generated bytes, so it is a generator or
 * adapter version bump and a reviewed golden diff.
 */

/** Version of the shared generator core (IR, printer, packaging). */
export const GENERATOR_VERSION = '0.1.0'

/** The current Terraform patch (checked 2026-09-24: checkpoint-api says 1.16.4). */
export const TERRAFORM_VERSION = '1.16.4'
/** The floor we promise in `required_version`; CI validates on it too. */
export const TERRAFORM_FLOOR_VERSION = '1.11.4'
export const TERRAFORM_REQUIRED_VERSION = '>= 1.11.0, < 2.0.0'

export interface ProviderPin {
  /** Local name used in `required_providers` and `provider` blocks. */
  name: string
  source: string
  constraint: string
  /** The version the static lock file records. */
  locked: string
}

export const AWS_PROVIDER: ProviderPin = { name: 'aws', source: 'hashicorp/aws', constraint: '>= 6.66.0, < 7.0.0', locked: '6.66.0' }
export const VSPHERE_PROVIDER: ProviderPin = { name: 'vsphere', source: 'vmware/vsphere', constraint: '>= 2.17.1, < 3.0.0', locked: '2.17.1' }

/** Platforms the static lock files carry hashes for (`terraform providers lock -platform=...`). */
export const LOCK_PLATFORMS = ['linux_amd64', 'darwin_arm64', 'windows_amd64'] as const
